    edges = s.get('neighbors') or []
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[j] > 0:
            if nearest[i] is None or d < nearest[i]:
                nearest[i] = d
    coordination = [0.0 for x in sites]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and nearest[i] is not None:
            if d <= 2.0 * nearest[i] and occ[j] > 0:
                coordination[i] += occ[j] * exp(1.0 - (d / nearest[i]) ** 6)
    total = sum(occ)
    return sum(occ[i] * coordination[i] for i in range(n)) / total if total > 0 else 0.0

